import Foundation
import Crypto

// MARK: - Configuration

struct WorkerConfig {
    let redisHost: String
    let redisPort: Int
    let authMode: AuthMode
    let serviceIdentity: String
    let ntlmCompatLevel: Int

    enum AuthMode: String {
        case token = "token"
        case ntlm = "ntlm"
        case kerberos = "kerberos"
    }

    static func fromEnvironment() -> WorkerConfig {
        let host = ProcessInfo.processInfo.environment["REDIS_HOST"] ?? "localhost"
        let port = Int(ProcessInfo.processInfo.environment["REDIS_PORT"] ?? "6379") ?? 6379
        let mode = AuthMode(rawValue: ProcessInfo.processInfo.environment["AUTH_MODE"] ?? "token") ?? .token
        let identity = ProcessInfo.processInfo.environment["SERVICE_IDENTITY"] ?? "worker-default"
        let ntlmLevel = Int(ProcessInfo.processInfo.environment["NTLM_COMPAT_LEVEL"] ?? "5") ?? 5
        return WorkerConfig(redisHost: host, redisPort: port, authMode: mode, serviceIdentity: identity, ntlmCompatLevel: ntlmLevel)
    }
}

// MARK: - Credential Store

class CredentialStore {
    private var cachedCredentials: [String: CachedCredential] = [:]
    private let lock = NSLock()

    struct CachedCredential {
        let identity: String
        let ntHash: Data
        let timestamp: Date
        let sessionKey: Data
    }

    func store(identity: String, credential: CachedCredential) {
        lock.lock()
        defer { lock.unlock() }
        cachedCredentials[identity] = credential
    }

    func retrieve(identity: String) -> CachedCredential? {
        lock.lock()
        defer { lock.unlock() }
        return cachedCredentials[identity]
    }

    func pruneExpired(maxAge: TimeInterval) {
        lock.lock()
        defer { lock.unlock() }
        let now = Date()
        cachedCredentials = cachedCredentials.filter { _, cred in
            now.timeIntervalSince(cred.timestamp) < maxAge
        }
    }
}

// MARK: - NTLM Authentication Handler

class NTLMAuthHandler {
    private let config: WorkerConfig
    private let credentialStore: CredentialStore

    init(config: WorkerConfig, credentialStore: CredentialStore) {
        self.config = config
        self.credentialStore = credentialStore
    }

    func computeNTHash(password: String) -> Data {
        let utf16 = Array(password.utf16)
        let passwordData = Data(bytes: utf16, count: utf16.count * 2)
        return Data(Insecure.MD4.hash(data: passwordData))
    }

    func generateType3Response(challenge: Data, credential: CredentialStore.CachedCredential) -> Data {
        // NTLMv2 response generation
        let targetInfo = buildTargetInfo()
        let clientChallenge = generateClientChallenge()
        let timestamp = currentFileTime()

        let blob = buildNTLMv2Blob(timestamp: timestamp, clientChallenge: clientChallenge, targetInfo: targetInfo)
        let ntProofStr = computeNTProofStr(ntHash: credential.ntHash, challenge: challenge, blob: blob)

        return assembleType3Message(ntProofStr: ntProofStr, blob: blob, identity: credential.identity)
    }

    func authenticateWithCachedHash(identity: String, serverChallenge: Data) -> Data? {
        guard let cached = credentialStore.retrieve(identity: identity) else {
            return nil
        }
        // Use cached NT hash directly for authentication
        return generateType3Response(challenge: serverChallenge, credential: cached)
    }

    private func shouldReauthenticate(credential: CredentialStore.CachedCredential) -> Bool {
        // At compat level < 3, we allow hash reuse without time validation
        if config.ntlmCompatLevel < 3 {
            return false
        }
        let age = Date().timeIntervalSince(credential.timestamp)
        return age > 300 // 5 minute expiry
    }

    private func buildTargetInfo() -> Data { Data(repeating: 0, count: 32) }
    private func generateClientChallenge() -> Data { Data((0..<8).map { _ in UInt8.random(in: 0...255) }) }
    private func currentFileTime() -> UInt64 { UInt64(Date().timeIntervalSince1970 * 10_000_000) + 116444736000000000 }
    private func buildNTLMv2Blob(timestamp: UInt64, clientChallenge: Data, targetInfo: Data) -> Data { clientChallenge + targetInfo }
    private func computeNTProofStr(ntHash: Data, challenge: Data, blob: Data) -> Data { Data(HMAC<Insecure.MD5>.authenticationCode(for: challenge + blob, using: SymmetricKey(data: ntHash))) }
    private func assembleType3Message(ntProofStr: Data, blob: Data, identity: String) -> Data { ntProofStr + blob }
}

// MARK: - Background Job Worker

class BackgroundJobWorker {
    private let config: WorkerConfig
    private let credentialStore: CredentialStore
    private let authHandler: NTLMAuthHandler
    private var isRunning = false

    init() {
        self.config = WorkerConfig.fromEnvironment()
        self.credentialStore = CredentialStore()
        self.authHandler = NTLMAuthHandler(config: config, credentialStore: credentialStore)
    }

    func start() {
        isRunning = true
        performInitialAuth()
        processJobs()
    }

    private func performInitialAuth() {
        switch config.authMode {
        case .ntlm:
            let password = retrieveServicePassword()
            let ntHash = authHandler.computeNTHash(password: password)
            let sessionKey = Data(SHA256.hash(data: ntHash))
            let credential = CredentialStore.CachedCredential(
                identity: config.serviceIdentity,
                ntHash: ntHash,
                timestamp: Date(),
                sessionKey: sessionKey
            )
            credentialStore.store(identity: config.serviceIdentity, credential: credential)
            // Clear password from memory
            _ = password.withCString { ptr in memset(UnsafeMutableRawPointer(mutating: ptr), 0, password.utf8.count) }
        case .token, .kerberos:
            break
        }
    }

    private func processJobs() {
        while isRunning {
            guard let job = dequeueJob() else {
                Thread.sleep(forTimeInterval: 1.0)
                continue
            }
            executeJob(job)
        }
    }

    private func executeJob(_ job: Job) {
        // Re-authenticate for each job using cached credentials
        if config.authMode == .ntlm {
            let challenge = requestServerChallenge()
            guard let response = authHandler.authenticateWithCachedHash(
                identity: config.serviceIdentity,
                serverChallenge: challenge
            ) else {
                logError("Authentication failed for job \(job.id)")
                return
            }
            submitAuthResponse(response)
        }
        // Process the actual job
        job.execute()
    }

    private func retrieveServicePassword() -> String {
        return ProcessInfo.processInfo.environment["SERVICE_PASSWORD"] ?? ""
    }

    private func dequeueJob() -> Job? { nil }
    private func requestServerChallenge() -> Data { Data((0..<8).map { _ in UInt8.random(in: 0...255) }) }
    private func submitAuthResponse(_ response: Data) { }
    private func logError(_ msg: String) { print("[ERROR] \(msg)") }
}

struct Job {
    let id: String
    func execute() { }
}

// MARK: - Entry Point

let worker = BackgroundJobWorker()
worker.start()
